func RenderTitledBox(title string, lines []string, width int) []string {
	if width < minBoxWidth {
		width = minBoxWidth
	}
	inner := width - 2

	borderStyle := lipgloss.NewStyle().
		Foreground(ColorViewportBorder).
		Background(ColorBackground)
	border := lipgloss.NormalBorder()
