		out = append(out, side+PadWithBg(truncateToWidth(line, inner), inner)+side)
	}
	out = append(out, borderStyle.Render(
		border.BottomLeft+strings.Repeat(border.Bottom, inner)+border.BottomRight))
	return out
}

