		Foreground(ColorTitleFg).
		Background(ColorBackground).
		Bold(true)

	rendered := titleStyle.Render(title)
	// " " + title + " " puis le remplissage jusqu'à width.
	used := 1 + lipgloss.Width(rendered) + 1
	fill := width - used
