// sectionsToLines splits rendered sections into individual lines with background separators
func sectionsToLines(sections []string, colWidth int) []string {
	emptyLine := theme.EmptyLineBg(colWidth)
	var lines []string
	for i, s := range sections {
		lines = append(lines, strings.Split(s, "\n")...)
		if i < len(sections)-1 {
			lines = append(lines, emptyLine)
		}
	}
	return lines
}

// View renders the dashboard as a two-column layout
func (m Model) View() string {
	colWidth := m.columnWidth()

	// Left column: GitLab, Services, Certificates, Workspaces
	leftSections := []string{
		m.renderGitLabSection(colWidth),
		m.renderServicesSection(colWidth),
		m.renderCertificatesSection(colWidth),
		m.renderWorkspacesSection(colWidth),
	}

	// Right column: OCI, Containers, Tools
	rightSections := []string{
		m.renderOCISection(colWidth),
		m.renderContainersSection(colWidth),
		m.renderToolsSection(colWidth),
	}

	// Split sections into lines
	leftLines := sectionsToLines(leftSections, colWidth)
	rightLines := sectionsToLines(rightSections, colWidth)

	// Equalize heights
	emptyLine := theme.EmptyLineBg(colWidth)
	maxH := len(leftLines)
	if len(rightLines) > maxH {
		maxH = len(rightLines)
	}
	for len(leftLines) < maxH {
		leftLines = append(leftLines, emptyLine)
	}
	for len(rightLines) < maxH {
		rightLines = append(rightLines, emptyLine)
	}

	// Combine columns line by line (no JoinHorizontal)
	var rows []string
	for i := 0; i < maxH; i++ {
		rows = append(rows, theme.PadWithBg(leftLines[i], colWidth)+theme.PadWithBg(rightLines[i], colWidth))
	}

	content := strings.Join(rows, "\n")
	return lipgloss.Place(m.width, m.height, lipgloss.Center, lipgloss.Top,
		lipgloss.NewStyle().Background(theme.ColorBackground).Padding(1).Render(content),
		lipgloss.WithWhitespaceBackground(theme.ColorBackground))
}

input.new_string:
// View renders the dashboard as a grid of titled boxes. Il n'y a pas de cadre
// extérieur : toutes les autres vues encadrent un objet (une table, un
// formulaire), le dashboard est fait de groupes hétérogènes qu'un cadre unique
// n'aiderait pas à lire.
func (m Model) View() string {
	t := layoutTier(m.width, m.height)
	colWidth := t.columnWidth(m.width)
	columns := m.columnsFor(t)

	rendered := make([][]string, len(columns))
	height := 0
	for i, col := range columns {
		rendered[i] = m.renderColumn(col, colWidth, t)
		if len(rendered[i]) > height {
			height = len(rendered[i])
		}
	}

	pad := theme.EmptyLineBg(sidePadding)
	gap := theme.EmptyLineBg(columnGap)
	blank := theme.EmptyLineBg(colWidth)

	lines := make([]string, 0, height+1)
	lines = append(lines, theme.EmptyLineBg(m.width))
	for i := 0; i < height; i++ {
		line := pad
		for c, col := range rendered {
			if c > 0 {
				line += gap
			}
			if i < len(col) {
				line += col[i]
			} else {
				line += blank
			}
		}
		lines = append(lines, theme.PadWithBg(line, m.width))
	}
	return strings.Join(lines, "\n")
}

// columnsFor distributes the active tab's sections over the palier's columns.
// À `wide`, la troisième colonne porte le contenu de l'onglet Resources : le
// palier décide où se trouve un fait, jamais s'il existe.
func (m Model) columnsFor(t tier) [][]section {
	overview, resources := overviewSections(), resourceSections()

	if m.activeTab == tabResources {
		if t.columns() == 1 {
			return [][]section{resources}
		}
		return [][]section{{resources[0]}, {resources[1]}}
	}

	switch t.columns() {
	case 3:
		return [][]section{{overview[0], overview[1]}, {overview[2], overview[3]}, resources}
	case 2:
		return [][]section{{overview[0], overview[1]}, {overview[2], overview[3]}}
	default:
		return [][]section{overview}
	}
}

// renderColumn stacks a column's boxes. Aucune ligne vide entre elles : leurs
// bordures séparent déjà, et à 30 lignes le budget vaut exactement deux boîtes.
func (m Model) renderColumn(sections []section, width int, t tier) []string {
	var lines []string
	for _, s := range sections {
		content := fitHeight(s.render(m, width), t.innerHeight(), width-2)
		lines = append(lines, theme.RenderTitledBox(s.title, content, width)...)
	}
	return lines
}

// fitHeight pads a section's content to the height its palier declares. Un
// renderer produit toujours le même nombre de lignes quel que soit l'état de
// ses données ; ce padding n'ajuste que la différence entre paliers.
func fitHeight(content []string, height, innerWidth int) []string {
	out := make([]string, 0, height)
	out = append(out, content...)
	for len(out) < height {
		out = append(out, theme.EmptyLineBg(innerWidth))
	}
	return out[:height]
}

