package dashboard

import (
	"strings"

	"github.com/charmbracelet/lipgloss"

	"github.com/anthnel/devdesk/internal/status"
	"github.com/anthnel/devdesk/internal/ui/help"
	"github.com/anthnel/devdesk/internal/ui/shortcut"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// View renders the dashboard as a grid of titled boxes. Il n'y a pas de cadre
// extérieur : toutes les autres vues encadrent un objet (une table, un
// formulaire), le dashboard est fait de groupes hétérogènes qu'un cadre unique
// n'aiderait pas à lire.
func (m Model) View() string {
	t := layoutTier(m.width, m.height)
	colWidth := t.columnWidth(m.width)
	columns := m.columnsFor(t)

	rendered := make([][]string, len(columns))
	height := 0
	for i, col := range columns {
		rendered[i] = m.renderColumn(col, colWidth, t)
		if len(rendered[i]) > height {
			height = len(rendered[i])
		}
	}

	pad := theme.EmptyLineBg(sidePadding)
	gap := theme.EmptyLineBg(columnGap)
	blank := theme.EmptyLineBg(colWidth)

	lines := make([]string, 0, height+1)
	lines = append(lines, theme.EmptyLineBg(m.width))
	for i := range height {
		var line strings.Builder
		line.WriteString(pad)
		for c, col := range rendered {
			if c > 0 {
				line.WriteString(gap)
			}
			if i < len(col) {
				line.WriteString(col[i])
			} else {
				line.WriteString(blank)
			}
		}
		lines = append(lines, theme.PadWithBg(line.String(), m.width))
	}
	return strings.Join(lines, "\n")
}

// columnsFor distributes the active tab's sections over the palier's columns.
// À `wide`, la troisième colonne porte le contenu de l'onglet Resources : le
// palier décide où se trouve un fait, jamais s'il existe.
func (m Model) columnsFor(t tier) [][]section {
	overview, resources := overviewSections(), resourceSections()

	if m.activeTab == tabResources {
		if t.columns() == 1 {
			return [][]section{resources}
		}
		return [][]section{{resources[0]}, {resources[1]}}
	}

	switch t.columns() {
	case 3:
		return [][]section{{overview[0], overview[1]}, {overview[2], overview[3]}, resources}
	case 2:
		return [][]section{{overview[0], overview[1]}, {overview[2], overview[3]}}
	default:
		return [][]section{overview}
	}
}

// renderColumn stacks a column's boxes. Aucune ligne vide entre elles : leurs
// bordures séparent déjà, et à 30 lignes le budget vaut exactement deux boîtes.
func (m Model) renderColumn(sections []section, width int, t tier) []string {
	var lines []string
	for _, s := range sections {
		content := fitHeight(s.render(m, width), t.innerHeight(), width-2)
		lines = append(lines, theme.RenderTitledBox(s.title, content, width)...)
	}
	return lines
}

// fitHeight pads a section's content to the height its palier declares. Un
// renderer produit toujours le même nombre de lignes quel que soit l'état de
// ses données ; ce padding n'ajuste que la différence entre paliers.
func fitHeight(content []string, height, innerWidth int) []string {
	out := make([]string, 0, height)
	out = append(out, content...)
	for len(out) < height {
		out = append(out, theme.EmptyLineBg(innerWidth))
	}
	return out[:height]
}

// filterComponents returns service components filtered by SSL type
func (m Model) filterComponents(sslOnly bool) []status.ComponentStatus {
	var result []status.ComponentStatus
	for _, c := range m.serviceComponents {
		isSSL := c.Type == status.TypeSSL
		if sslOnly == isSSL {
			result = append(result, c)
		}
	}
	return result
}

// countStatuses returns OK, Down, Error counts
func countStatuses(components []status.ComponentStatus) (ok, down, errCount int) {
	for _, c := range components {
		switch c.Status {
		case status.StatusOK:
			ok++
		case status.StatusDown:
			down++
		default:
			errCount++
		}
	}
	return
}

// HeaderView interface

// Frameless tells the router to draw no viewport border for this view. Le
// dashboard est la seule vue qui n'encadre pas un objet unique — voir View().
func (m Model) Frameless() bool {
	return true
}

// GetFooterHeight returns the footer height for this view (Rule 124):
// tab bar + empty line + info line.
func (m Model) GetFooterHeight() int {
	return 3
}

// RenderFooter draws the tab bar and the age of the data (Rule 124).
//
// L'âge n'est pas de la décoration : avec des libellés qui restent en place et
// des valeurs à `-`, une donnée périmée ressemble exactement à une donnée
// fraîche. C'est le prix des placeholders, pas un ornement.
func (m Model) RenderFooter(width int) string {
	tabs := []theme.TabItem{{Label: "Overview"}, {Label: "Resources"}}
	tabBar := theme.PadWithBg(theme.Bg(" ")+theme.RenderTabs(tabs, int(m.activeTab)), width)

	info := theme.EmptyLineBg(width)
	if age := theme.TimeAgo(m.lastRefresh); age != "" {
		info = lipgloss.NewStyle().
			Foreground(theme.ColorHighlight).
			Background(theme.ColorBackground).
			Width(width).
			Align(lipgloss.Center).
			Render("Updated " + age)
	}

	return tabBar + "\n" + theme.EmptyLineBg(width) + "\n" + info
}

// GetShortcuts returns the keyboard shortcuts for the header
func (m Model) GetShortcuts() shortcut.Shortcuts {
	shortcuts := []shortcut.Shortcut{
		{Key: "ctrl+r", Description: "Refresh"},
	}
	if m.shared.IsAuthenticated {
		shortcuts = append(shortcuts,
			shortcut.Shortcut{Key: "m", Description: "Open MRs"},
			shortcut.Shortcut{Key: "i", Description: "Open issues"},
		)
	}
	shortcuts = append(shortcuts,
		shortcut.Shortcut{Key: "alt+:", Description: "Command"},
		shortcut.Shortcut{Key: "?", Description: "Help"},
	)
	return shortcuts
}

// GetTitle returns the view title
func (m Model) GetTitle() string {
	return theme.IconDashboard + " Dashboard"
}

// GetIcon returns the view icon
func (m Model) GetIcon() string {
	return ""
}

// GetHeaderInfo returns the key-value info for the header
func (m Model) GetHeaderInfo(context string) []shortcut.HeaderInfo {
	return []shortcut.HeaderInfo{
		{Key: "Context", Value: context, Style: theme.HeaderValueStyle},
	}
}

// GetHelpContent returns help content for the dashboard (Rule 114)
func (m Model) GetHelpContent() help.Content {
	return help.Content{
		Title:       "Dashboard",
		Description: "The dashboard provides an overview of all your DevSecOps resources in a two-column layout. Left column shows GitLab activity, service health, SSL certificates, and workspaces. Right column shows OCI resources, container states, and available tools.",
		KeyBindings: []help.KeyBinding{
			{Key: "ctrl+r", Description: "Refresh all dashboard data"},
			{Key: "m", Description: "Open assigned merge requests in browser (requires authentication)"},
			{Key: "i", Description: "Open assigned issues in browser (requires authentication)"},
			{Key: "alt+:", Description: "Open command mode to navigate to other views"},
			{Key: "?", Description: "Show this help"},
		},
		Sections: []help.Section{
			{
				Title: "GitLab",
				Body:  "Displays your GitLab activity: assigned merge requests, MRs awaiting your review, and assigned issues. Requires authentication via :gitlab-auth.",
			},
			{
				Title: "Services & Certificates",
				Body:  "Shows the health of monitored services (HTTP, ICMP, DNS) separately from SSL certificate monitors. Green when all OK, yellow when degraded, red when all down. Configure in :status view.",
			},
			{
				Title: "Workspaces",
				Body:  "Shows the number of local workspaces and total disk usage of the workspaces directory.",
			},
			{
				Title: "OCI Resources",
				Body:  "Displays counts and disk usage for Docker images, containers, and volumes via 'docker system df'.",
			},
			{
				Title: "Containers",
				Body:  "Shows container counts by state: running, stopped, and paused. Requires the docker CLI.",
			},
			{
				Title: "Tools",
				Body:  "Lists detected DevSecOps tools (Docker, Trivy, Gitleaks, Git) with their versions and source (binary or docker image).",
			},
			{
				Title: "Navigation",
				Body:  "Press alt+: to open command mode, then type a view name: status for monitors, gitlab-auth for authentication, gitlab-explorer for browsing projects, workspaces for file management, containers for Docker management, oci-resources for OCI resource management, security for scanning.\n\nA bare : opens command mode too, but only when no text field has focus — inside one it types a colon, which values like https://trivy-server:4954 need. alt+: always works.",
			},
		},
	}
}

