// La boîte Host compte les outils, l'onglet Resources les nomme : savoir
// *lequel* manque est un détail de la machine, et un compteur ne le dit pas.
func TestTheToolsAreCountedOnTheOverviewAndNamedInResources(t *testing.T) {
	m, _ := loadedModel(t)

	overview := plain(m.View())
	if !strings.Contains(overview, "of 5 available") {
		t.Errorf("the Host box does not count the tools:\n%s", overview)
	}
	if strings.Contains(overview, "Gitleaks") {
		t.Error("the Overview names a tool — that detail belongs to the Resources tab")
	}

	m.activeTab = tabResources
	resources := plain(m.View())
	for _, name := range knownTools {
		if !strings.Contains(resources, name) {
			t.Errorf("the Resources tab does not name %q:\n%s", name, resources)
		}
	}
}

// Un outil absent de la détection garde sa ligne : la faire disparaître se
// lirait comme « il n'y en a que quatre ».
func TestAnUndetectedToolKeepsItsLine(t *testing.T) {
