	m = feed(t, m, ToolsDetectedMsg{Tools: []shared.ToolInfo{{Name: "Docker", Available: true}}})

	lines := renderToolsSection(m, 40)
	if len(lines) != len(knownTools) {
		t.Fatalf("the tools box rendered %d lines for %d known tools", len(lines), len(knownTools))
	}
	if !containsLine(lines, "Gitleaks") {
		t.Errorf("an undetected tool lost its line: %q", lines)
	}
}

