12	)
13	
14	// View renders the dashboard as a grid of titled boxes. Il n'y a pas de cadre
15	// extérieur : toutes les autres vues encadrent un objet (une table, un
16	// formulaire), le dashboard est fait de groupes hétérogènes qu'un cadre unique
17	// n'aiderait pas à lire.
18	func (m Model) View() string {
19		t := layoutTier(m.width, m.height)
20		colWidth := t.columnWidth(m.width)
21		columns := m.columnsFor(t)
22	
23		inner := m.innerHeight(columns, colWidth)
24	
25		rendered := make([][]string, len(columns))
26		height := 0
27		for i, col := range columns {
28			rendered[i] = m.renderColumn(col, colWidth, inner)
29			if len(rendered[i]) > height {
30				height = len(rendered[i])
31			}
32		}
33	
34		pad := theme.EmptyLineBg(sidePadding)
35		gap := theme.EmptyLineBg(columnGap)
36		blank := theme.EmptyLineBg(colWidth)
37	
38		lines := make([]string, 0, height+1)
39		lines = append(lines, theme.EmptyLineBg(m.width))
40		for i := range height {
41			var line strings.Builder
42			line.WriteString(pad)
43			for c, col := range rendered {
44				if c > 0 {
45					line.WriteString(gap)
46				}
47				if i < len(col) {
48					line.WriteString(col[i])
49				} else {
50					line.WriteString(blank)
51				}
52			}
53			lines = append(lines, theme.PadWithBg(line.String(), m.width))
54		}
55		return strings.Join(lines, "\n")
56	}
57	
58	// columnsFor distributes the active tab's sections over the palier's columns.
59	// À `wide`, la troisième colonne porte le contenu de l'onglet Resources : le
60	// palier décide où se trouve un fait, jamais s'il existe.
61	func (m Model) columnsFor(t tier) [][]section {
62		overview, resources := overviewSections(), resourceSections()
63	
64		if m.activeTab == tabResources {
65			return distribute(resources, t.columns())
66		}
67		if t.columns() == 3 {
68			return append(distribute(overview, 2), resources)
69		}
70		return distribute(overview, t.columns())
71	}
72	
73	// distribute lays sections into `cols` columns, filling each column top to
74	// bottom — reading order down a column, which is how a stack of boxes is read.
75	func distribute(sections []section, cols int) [][]section {
76		if cols < 1 {
77			cols = 1
78		}
79		perColumn := (len(sections) + cols - 1) / cols
80	
81		out := make([][]section, 0, cols)
82		for start := 0; start < len(sections); start += perColumn {
83			out = append(out, sections[start:min(start+perColumn, len(sections))])
84		}
85		return out
86	}
87	
88	// innerHeight is the content height every box on screen fills, borders
89	// excluded: the tallest section of the frame.
90	//
91	// Elle est **dérivée des sections**, pas déclarée par le palier. Une constante
92	// pourrait tronquer une section qui grandit — un graphe ajouté en phase 3, une
93	// ligne ajoutée à Health en phase 4 — et la troncature ne se voit pas : la
94	// boîte reste bien formée, elle perd juste sa dernière ligne. Ce qui reste
95	// figé, et c'est le contrat de la phase 1, c'est qu'une section rende le même
96	// nombre de lignes quel que soit l'état de ses données.
97	func (m Model) innerHeight(columns [][]section, width int) int {
98		height := nominalInnerHeight
99		for _, col := range columns {
100			for _, s := range col {
101				if n := len(s.render(m, width, t)); n > height {
102					height = n
103				}
104			}
105		}
106		return height
107	}
108	
109	// renderColumn stacks a column's boxes. Aucune ligne vide entre elles : leurs
110	// bordures séparent déjà, et à 30 lignes le budget vaut exactement deux boîtes.
111	func (m Model) renderColumn(sections []section, width, inner int) []string {
112		var lines []string
113		for _, s := range sections {
114			content := padTo(s.render(m, width, t), inner, theme.BoxContentWidth(width))
115			lines = append(lines, theme.RenderTitledBox(s.title, content, width)...)
116		}
117		return lines
118	}
119	
120	// padTo fills a section's content out to the frame's box height. Il ne tronque
121	// pas : innerHeight est calculée sur ces mêmes sections, donc une ligne perdue
122	// ici serait un bug de calcul, pas un débordement à absorber.
123	func padTo(content []string, height, innerWidth int) []string {
124		out := make([]string, 0, height)
125		out = append(out, content...)
126		for len(out) < height {
127			out = append(out, theme.EmptyLineBg(innerWidth))
128		}
129		return out
130	}
131	
132	// filterComponents returns service components filtered by SSL type
133	func (m Model) filterComponents(sslOnly bool) []status.ComponentStatus {
134		var result []status.ComponentStatus
135		for _, c := range m.serviceComponents {
136			isSSL := c.Type == status.TypeSSL
137			if sslOnly == isSSL {
138				result = append(result, c)
139			}
140		}
141		return result
142	}
143	
144	// countStatuses returns OK, Down, Error counts
145	func countStatuses(components []status.ComponentStatus) (ok, down, errCount int) {
146		for _, c := range components {
147			switch c.Status {
148			case status.StatusOK:
149				ok++
150			case status.StatusDown:
151				down++
152			default:
153				errCount++
154			}
155		}
156		return
157	}
