159	// HeaderView interface
160	
161	// Frameless tells the router to draw no viewport border for this view. Le
162	// dashboard est la seule vue qui n'encadre pas un objet unique — voir View().
163	func (m Model) Frameless() bool {
164		return true
165	}
166	
167	// GetFooterHeight returns the footer height for this view (Rule 124): an empty
168	// line, an info line, and the tab bar when there is more than one tab.
169	func (m Model) GetFooterHeight() int {
170		if m.showsTabBar() {
171			return 3
172		}
173		return 2
174	}
175	
176	// showsTabBar reports whether a tab bar is worth a line. Un seul onglet n'est
177	// pas un choix : la barre dirait « vous êtes ici », ce que l'écran dit déjà.
178	func (m Model) showsTabBar() bool {
179		return tabCountFor(layoutTier(m.width, m.height)) > 1
180	}
181	
182	// RenderFooter draws the tab bar and the age of the data (Rule 124).
183	//
184	// L'âge n'est pas de la décoration : avec des libellés qui restent en place et
185	// des valeurs à `-`, une donnée périmée ressemble exactement à une donnée
186	// fraîche. C'est le prix des placeholders, pas un ornement.
187	func (m Model) RenderFooter(width int) string {
188		info := theme.EmptyLineBg(width)
189		if age := theme.TimeAgo(m.lastRefresh); age != "" {
190			info = lipgloss.NewStyle().
191				Foreground(theme.ColorHighlight).
192				Background(theme.ColorBackground).
193				Width(width).
194				Align(lipgloss.Center).
195				Render("Updated " + age)
196		}
197	
198		if !m.showsTabBar() {
199			return theme.EmptyLineBg(width) + "\n" + info
200		}
201	
202		tabs := []theme.TabItem{{Label: "Overview"}, {Label: "Resources"}}
203		tabBar := theme.PadWithBg(theme.Bg(" ")+theme.RenderTabs(tabs, int(m.activeTab)), width)
204		return tabBar + "\n" + theme.EmptyLineBg(width) + "\n" + info
205	}
