func styleOf(params string) string {
	fields := strings.Split(params, ";")
	var css []string

	for i := 0; i < len(fields); i++ {
		switch fields[i] {
		case "", "0":
			return ""
		case "1":
			css = append(css, "font-weight:600")
		case "38", "48":
			if i+4 < len(fields) && fields[i+1] == "2" {
				prop := "color"
				if fields[i] == "48" {
					prop = "background"
				}
				css = append(css, fmt.Sprintf("%s:rgb(%s,%s,%s)", prop,
					num(fields[i+2]), num(fields[i+3]), num(fields[i+4])))
				i += 4
			}
		}
	}
	return strings.Join(css, ";")
}

func num(s string) string {
	if _, err := strconv.Atoi(s); err != nil {
		return "0"
	}
	return s
}

