	m, _ := loadedModel(t)
	// 30 rows less the header (9), the title line (1) and the footer (3).
	const contentHeight = 30 - 9 - 1 - 3
	m = feed(t, m, tea.WindowSizeMsg{Width: 120, Height: contentHeight})

