		// `docker stats`, sur son horloge propre (≈ 2 s par appel mesuré).
		row("CPU", dockerPercent(m, func(a docker.Aggregate) float64 { return a.CPUPercent })),
	)
	lines = append(lines, renderChart(m.dockerSamples, theme.BoxContentWidth(width), m.chartHeight(t), 100)...)
	return append(lines, row("RAM", dockerPercent(m, func(a docker.Aggregate) float64 { return a.MemPercent })))
}

// dockerState renders one container-state count, telling "not read yet" from
// "Docker is not there" the way every other value does.
func dockerState(m Model, pick func(shared.DockerStats) int) string {
	switch {
	case m.loadingDocker:
		return unknownValue
	case m.dockerStats == nil || !m.dockerStats.Available:
		return unavailableValue
	default:
		return countValue(pick(*m.dockerStats))
	}
}

