package app

import (
	"fmt"
	"html"
	"os"
	"os/exec"
	"regexp"
	"strconv"
	"strings"
	"testing"
	"time"

	tea "github.com/charmbracelet/bubbletea"
	"github.com/charmbracelet/lipgloss"
	"github.com/muesli/termenv"

	"github.com/anthnel/devdesk/internal/command"
	"github.com/anthnel/devdesk/internal/config"
	"github.com/anthnel/devdesk/internal/docker"
	"github.com/anthnel/devdesk/internal/metrics"
	"github.com/anthnel/devdesk/internal/scan"
	"github.com/anthnel/devdesk/internal/shared"
	"github.com/anthnel/devdesk/internal/status"
	"github.com/anthnel/devdesk/internal/ui/dashboard"
)

// Rend le dashboard complet (header, règle de titre, grille, footer) en HTML.
// Jetable : sert à envoyer une capture.
func TestZZScreenshot(t *testing.T) {
	out := os.Getenv("ZZ_OUT")
	if out == "" {
		t.Skip("set ZZ_OUT to render a screenshot")
	}
	if real := os.Getenv("ZZ_HOME"); real != "" {
		t.Setenv("HOME", real)
		t.Setenv("USERPROFILE", real)
	}

	restore := lipgloss.ColorProfile()
	lipgloss.SetColorProfile(termenv.TrueColor)
	t.Cleanup(func() { lipgloss.SetColorProfile(restore) })

	width, height := 250, 60
	cfg, err := config.Load()
	if err != nil {
		t.Logf("falling back to the test config: %v", err)
		cfg = testConfig()
	}
	app := newWithSize(cfg, width, height)
	app.currentView = command.ViewDashboard
	app.resize(width, height)

	send(t, app,
		dashboard.StatusCheckMsg{Result: status.RunCheck(cfg)},
		dashboard.ToolsDetectedMsg{Tools: detectedTools(cfg)},
	)

	counters := metrics.Counters{}
	for range 120 {
		var sample metrics.HostSample
		sample, counters = metrics.SampleHost(counters)
		send(t, app, dashboard.HostSampleMsg{Sample: sample, Counters: counters})
		time.Sleep(30 * time.Millisecond)
	}

	send(t, app,
		dashboard.DiskUsageMsg{Workspaces: metrics.Disk(".")},
		dashboard.DockerMetricsMsg{Aggregate: docker.FetchAggregateMetrics()},
		dashboard.OCIStatsMsg{Stats: sharedOCI()},
		dashboard.DockerStatsMsg{Stats: sharedDocker()},
		dashboard.WorkspaceStatsMsg{Count: countDirs(cfg.App.WorkspacesDir)},
	)

	if err := os.WriteFile(out, []byte(toHTML(app.View())), 0o644); err != nil {
		t.Fatalf("writing %s: %v", out, err)
	}
	t.Logf("wrote %s", out)
}

func send(t *testing.T, a *App, msgs ...tea.Msg) {
	t.Helper()
	view := a.views[command.ViewDashboard]
	for _, msg := range msgs {
		view, _ = view.Update(msg)
	}
	a.views[command.ViewDashboard] = view
}

func detectedTools(cfg *config.Config) []shared.ToolInfo {
	deps := scan.CheckDependencies(cfg.Scan)
	return []shared.ToolInfo{
		{Name: "Docker", Available: lookPath("docker"), Source: "binary"},
		{Name: "Trivy", Available: deps.TrivyAvailable, Version: deps.TrivyVersion, Source: string(deps.TrivySource)},
		{Name: "Gitleaks", Available: deps.GitleaksAvailable, Version: deps.GitleaksVersion, Source: string(deps.GitleaksSource)},
		{Name: "Net Diag", Available: lookPath("docker"), Source: "image"},
		{Name: "Git", Available: lookPath("git"), Source: "binary"},
	}
}

func countDirs(dir string) int {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return 0
	}
