// inventaire qui l'est.
func TestAnUndatedEntryDoesNotBecomeTheOldestScan(t *testing.T) {
	var p posture
	p.add(0, 0, day(2))
	p.add(1, 1, time.Time{})

	if p.Oldest.IsZero() {
		t.Error("an entry with no timestamp became the oldest scan")
	}
	if p.Targets != 2 {
		t.Errorf("Targets = %d — an undated entry is still a scanned target", p.Targets)
	}
}

