// chartTextRows is the tallest run of text rows a chart-bearing box carries
// besides its charts (Host: CPU, RAM, memory detail, Disk, Tools).
const chartTextRows = 5

// chartsPerBox is what a chart-bearing box holds — CPU and RAM, RX and TX. Deux
// séries par boîte, donc la hauteur libre se partage en deux.
const chartsPerBox = 2

// Bornes : en dessous de 3 lignes le braille n'a pas de quoi montrer sa
// résolution verticale, et au-delà de 12 un graphe de pourcentage n'apprend
// plus rien de la hauteur qu'il prend.
const (
	minBrailleHeight = 3
	maxChartHeight   = 12
)

// chartHeight is how many lines a chart gets.
//
// À `standard` elle vaut 1 : la grille y tient tout juste, donc un graphe prend
// la place d'une ligne vide au lieu de s'ajouter. À `wide` elle est **calculée
// sur la place réellement disponible** plutôt que figée à quatre — c'est ce qui
// remplit un terminal haut au lieu d'y laisser un tiers d'écran vide, et ça
// suit la fenêtre quand elle change.
func (m Model) chartHeight(t tier) int {
	if t != tierWide {
		return 1
	}
	// Deux rangées de boîtes, chacune coûtant son chrome et ses lignes de texte.
	free := (m.height - 2*theme.BoxChrome - 2*chartTextRows) / 2
	return min(max(free/chartsPerBox, minBrailleHeight), maxChartHeight)
}

