		{Name: "unreachable", Type: status.TypeSSL, Status: status.StatusDown},
	}

	if got := stripANSI(nearestExpiry(certs, false)); got != "-" {
		t.Errorf("nearestExpiry = %q for a certificate that could not be read, want %q", got, "-")
	}
}

