	if got := stripANSI(nearestExpiry(nil, false)); !strings.Contains(got, "none configured") {
		t.Errorf("nearestExpiry = %q with no SSL monitor", got)
	}
}

// ── Reclaimable ──────────────────────────────────────────────────────────────

// Docker en place et rien à récupérer n'est pas Docker absent.
func TestNothingToReclaimIsNotAnAbsentDocker(t *testing.T) {
	m, _ := loadedModel(t) // its OCI stats carry no reclaimable figure

	got := lineStartingWith(renderStorageSection(m, 60, tierStandard), "Docker")
	if !strings.Contains(got, "nothing to reclaim") {
		t.Errorf("with Docker present and nothing to reclaim, the row shows %q", got)
	}

	absent := lineStartingWith(renderStorageSection(withNoDocker(t), 60, tierStandard), "Docker")
	if !strings.Contains(absent, "n/a") {
		t.Errorf("with Docker absent, the row shows %q, want n/a", absent)
	}
}

