	} else if m.dockerStats != nil && m.dockerStats.Available {
		d := m.dockerStats
		containers = countValue(d.Running+d.Stopped+d.Paused) + theme.Bg(" total")
		if t != tierWide {
			// Sans l'arbre, le total seul ne dit pas combien tournent.

