// postureBranches renders one family's tally, one figure per node.
//
// `critical` et `high` ont chacun leur branche plutôt que de partager une
// ligne : deux nombres côte à côte demandent de retenir lequel est lequel, et
// c'est précisément le chiffre qu'on lit en diagonale.
func postureBranches(p posture, side postureSide) []string {
	if !p.Read {
		return []string{
			branch(false, "scanned", unknownValue),
			branch(false, "critical", unknownValue),
			branch(false, "high", unknownValue),
			branch(true, "oldest", unknownValue),
		}
	}
	return []string{
		branch(false, "scanned", countValue(side.Targets)+theme.Bg(" targets")),
		branch(false, "critical", severityCount(side.Critical)),
		branch(false, "high", severityCount(side.High)),
		branch(true, "oldest", scanAge(side)),
	}
}

