// diskUsed says how full the volume holding the workspaces is.
//
// **Ce n'est pas la taille de l'arborescence.** La mesurer demande un `du`,
// dont le coût grandit avec les données de l'utilisateur et qui a justement été
// retiré du tour lent (§3.19) ; le volume, lui, répond en 1 ms. C'est aussi la
// question qui se décide : une arborescence de 40 Go n'appelle rien, un volume
// à 97 % appelle quelque chose.
//
// Il complète le `Disk` de la boîte Host plutôt que de le répéter : celui-ci dit
// ce qui reste, celui-là ce qui est pris, et c'est le second qui a sa place sous
// le chemin dont il parle.
func diskUsed(d metrics.DiskUsage) string {
	if !d.OK {
		return unknownValue
	}
	return theme.Bg(humanBytes(d.Used)) +
		theme.DimStyle.Render(fmt.Sprintf(" used  %.0f%%", d.UsedPercent))
}

