// nodeUnder returns the named node of the tree a heading opens. Les deux arbres
// de posture portent les mêmes libellés, donc chercher « unscanned » dans toute
// la boîte rendrait toujours celui des images.
func nodeUnder(lines []string, heading, label string) string {
	for i, line := range lines {
		if stripANSI(line) != heading {
			continue
		}
		for _, node := range lines[i+1:] {
			plain := stripANSI(node)
			if strings.HasPrefix(plain, theme.IconTreeBranch+label) || strings.HasPrefix(plain, theme.IconTreeEnd+label) {
				return plain
			}
		}
	}
	return ""
}

