// L'espace disque pend du chemin dont il parle, et c'est celui qui est *pris* :
// la boîte Host dit déjà ce qui reste, et c'est le remplissage qui se décide.
func TestTheWorkspacesTreeReportsTheSpaceTaken(t *testing.T) {
	got := nodeUnder(renderCodeSection(loadedOnly(t), 60, tierWide), "Workspaces", "disk")

	for _, want := range []string{"290.0 GB", "used", "58%"} {
		if !strings.Contains(got, want) {
			t.Errorf("the disk node reads %q, want it to carry %q", got, want)
		}
	}
	if strings.Contains(got, "free") {
		t.Errorf("the disk node reads %q — free space is the Host box's line", got)
	}
}

