// statusBranches renders one node per state. Les trois sont toujours là, y
// compris à zéro : une branche absente se lit comme un état qu'on ne surveille
// pas, et c'est l'inverse de ce qu'un zéro veut dire.
func statusBranches(components []status.ComponentStatus, loading bool) []string {
	if loading {
		return []string{
			branch(false, "up", unknownValue),
			branch(false, "down", unknownValue),
			branch(true, "error", unknownValue),
		}
	}
	if len(components) == 0 {
		return []string{
			branch(true, "none configured", theme.Bg("")),
			theme.Bg(""),
			theme.Bg(""),
		}
	}

