	return []string{
		branch(false, "up", countValue(ok)+theme.Bg("  ")+theme.StatusOKStyle.Render(theme.IconOK)),
		branch(false, "down", failureCount(down, theme.IconError, theme.StatusDownStyle)),
		branch(true, "error", failureCount(errCount, theme.IconWarning, theme.StatusErrorStyle)),
	}
}

