func TestTheExpiryHangsFromTheCertificates(t *testing.T) {
	m := healthModel(t, []status.ComponentStatus{
		{Name: "web", Type: status.TypeHTTPS, Status: status.StatusOK},
		certWithDays("google.com", 58),
	})
