	// Les moniteurs n'ont pas d'échéance, donc pas de nœud.
	monitors, _ := healthColumns(m)
	if got := nodeUnder(monitors, "Monitors", "expiry"); got != "" {
		t.Errorf("the Monitors tree grew an expiry node: %q", got)
	}
}

