func sideBySide(left, right []string, width int) []string {
	half := max(width/2, 1)
	out := make([]string, max(len(left), len(right)))
	for i := range out {
		var l, r string
		if i < len(left) {
			l = theme.Truncate(left[i], half)
		}
		if i < len(right) {
			r = theme.Truncate(right[i], width-half)
		}
		out[i] = theme.PadWithBg(l, half) + r
	}
	return out
}

