	// propre était jetée — or c'est elle qui répond le plus souvent à « où est
	// passé le disque ».
	if got.BuildCacheSize != "2GB" {
		t.Errorf("BuildCacheSize = %q, want %q", got.BuildCacheSize, "2GB")
	}
}

