package dashboard

import (
	"log"
	"time"

	"github.com/anthnel/devdesk/internal/cache"
)

// posture is what the scan caches say about the current context, without
// running anything: c'est ce qui relie le dashboard à l'inventaire de §3.11
// sans lancer un seul scan (Rule 126).
type posture struct {
	// Read tells "the caches were consulted" apart from "there is nothing in
	// them" — sans lui, un cache vide et un cache jamais lu affichent le même
	// zéro, et l'un des deux serait un mensonge.
	Read bool

	// Les deux caches sont gardés séparés parce qu'ils ne se corrigent pas de
	// la même façon : une CRITICAL dans une image se règle en changeant de tag,
	// dans un dépôt en changeant du code. Les sommer donnait un total sur
	// lequel on ne pouvait rien décider.
	Images       postureSide
	Repositories postureSide
}

// postureSide is one family's tally.
//
// Le décompte des HIGH est parti avec son affichage : la boîte montre désormais
// combien de cibles n'ont jamais été scannées, ce qui se décide (lancer un scan)
// là où un HIGH de plus ne se décidait pas. Un champ que plus personne ne lit se
// lit comme une donnée qu'on a oublié d'afficher.
type postureSide struct {
	Targets  int
	Critical int
	// Oldest is the age of the least recently scanned target: c'est la question
	// utile, parce qu'un compteur de CRITICAL vieux de trois semaines est un
	// compteur sur du code qui n'existe plus.
	Oldest time.Time
}

// Total folds both families, for the paliers too narrow to show them apart.
func (p posture) Total() postureSide {
	total := p.Images
	total.Targets += p.Repositories.Targets
	total.Critical += p.Repositories.Critical
	if o := p.Repositories.Oldest; !o.IsZero() && (total.Oldest.IsZero() || o.Before(total.Oldest)) {
		total.Oldest = o
	}
	return total
}

// readPosture sums both caches for one context. Un cache illisible n'est pas
// une posture vide : il rend Read=false, donc `-` et non `0`.
func readPosture(context string) posture {
	images, errImages := cache.NewImageScanCache(context)
	workspaces, errWorkspaces := cache.NewWorkspaceScanCache(context)
	if errImages != nil || errWorkspaces != nil {
		log.Printf("ERROR [dashboard] reading the scan caches: %v / %v", errImages, errWorkspaces)
		return posture{}
	}

	p := posture{Read: true}
	for _, entry := range images.GetAll() {
		p.Images.add(entry.Critical, entry.ScannedAt)
	}
	for _, entry := range workspaces.GetAll() {
		p.Repositories.add(entry.Critical, entry.ScannedAt)
	}
	return p
}

// add folds one scanned target into a family's tally.
func (p *postureSide) add(critical int, scannedAt time.Time) {
	p.Targets++
	p.Critical += critical

	// Une entrée sans horodatage ne rajeunit pas la posture : le zéro d'un
	// time.Time serait le plus ancien de tous et ferait lire « jamais scanné »
	// à un inventaire qui l'est.
	if scannedAt.IsZero() {
		return
	}
	if p.Oldest.IsZero() || scannedAt.Before(p.Oldest) {
		p.Oldest = scannedAt
	}
}

// ── Coverage ─────────────────────────────────────────────────────────────────
//
// Ce que les caches savent, c'est ce qui a été scanné. Combien il en reste
// demande l'autre moitié — l'inventaire — et celle-ci est déjà dans le modèle :
// `docker system df` compte les images, `fetchWorkspaceStats` les dépôts. La
// soustraction se fait donc ici, et non dans readPosture, qui ne lit que des
// fichiers de cache et n'a aucune raison d'aller interroger Docker.
//
// Les trois retournent `(n, mesuré)` plutôt qu'un entier : sans le second, un
// inventaire pas encore chargé rendrait un zéro, et « rien à scanner » est
// exactement le contraire de « on ne sait pas encore ».

// unscannedImages counts the local images that carry no cache entry.
func (m Model) unscannedImages() (int, bool) {
	if !m.posture.Read || m.loadingOCI || m.ociStats == nil || !m.ociStats.Available {
		return 0, false
	}
	return uncovered(m.ociStats.ImagesCount, m.posture.Images.Targets), true
}

// unscannedRepositories counts the workspaces that carry no cache entry.
func (m Model) unscannedRepositories() (int, bool) {
	if !m.posture.Read || m.loadingWorkspaces {
		return 0, false
	}
	return uncovered(m.workspaceCount, m.posture.Repositories.Targets), true
}

// unscannedTotal folds both, for the paliers too narrow to show them apart. Une
// seule moitié manquante suffit à rendre le total non mesuré : la somme d'un
// nombre et d'une inconnue est une inconnue.
func (m Model) unscannedTotal() (int, bool) {
	images, okImages := m.unscannedImages()
	repositories, okRepositories := m.unscannedRepositories()
	if !okImages || !okRepositories {
		return 0, false
	}
	return images + repositories, true
}

// uncovered is the inventory minus what has been scanned, floored at zero: le
// cache garde l'entrée d'une image supprimée depuis, donc la différence peut
// passer sous zéro — et « il en reste moins que zéro à scanner » n'est pas une
// phrase. Le plancher dit ce qu'il faut en retenir : plus rien à scanner.
func uncovered(inventory, scanned int) int {
	return max(inventory-scanned, 0)
}

package dashboard

import "github.com/anthnel/devdesk/internal/ui/theme"

// tier is the dashboard's layout palier. Un terminal ne sait pas qu'il est 4K :
// il connaît des colonnes et des lignes, et deux tailles de police sur un même
// écran font deux terminaux. Le palier se calcule donc sur tea.WindowSizeMsg,
// et sur les deux dimensions séparément — la largeur décide du nombre de
// colonnes, la hauteur de ce qui tient.
type tier int

const (
	tierCompact tier = iota
	tierStandard
	tierWide
)

// Palier thresholds. Below `standard` the dashboard stacks; at `wide` it opens
// a third column, because two columns of a 240-cell terminal give 118-cell
// boxes to write "MRs 3 assigned" in.
//
// **Le nombre de colonnes ne dépend que de la largeur, et c'est un test qui
// l'a imposé.** Réduire les colonnes quand le terminal raccourcit est à
// l'envers : moins de colonnes veut dire plus de boîtes empilées, donc *plus*
// de hauteur nécessaire. À douze lignes de contenu, une grille 2×2 en perd six
// et une colonne unique en perd vingt-quatre. La hauteur ne gouverne donc que
// `wide`, dont les graphes braille sont réellement plus hauts.
//
// La hauteur est en lignes de *contenu*, pas en lignes de terminal : la vue
// reçoit ce que le routeur lui laisse — header 9, ligne de titre 1, footer 3.
const (
	standardMinWidth = 100
	wideMinWidth     = 180
	// La grille à trois colonnes empile trois rangées et ses boîtes portent des
	// arbres : son squelette — sans une seule courbe — fait une quarantaine de
	// lignes. En dessous, deux colonnes en perdent bien moins, ce que
	// TestTheChosenPalierLosesTheFewestLines vérifie à chaque hauteur.
	wideMinHeight = 42
)

// gridHeight is what a two-row grid of boxes needs, in content lines.
//
// **Le viewport du routeur ne défile pas** : rien ne lui transmet de touche, il
// coupe. Un layout trop haut ne fait donc pas apparaître une barre de
// défilement, il perd des lignes en silence — ce que §3.19 corrige par
// ailleurs. En dessous de gridHeight() aucun layout ne tient, et le palier ne
// choisit plus le meilleur mais le moins mauvais.
// Elle est **mesurée**, pas calculée : une constante décrivant la hauteur des
// boîtes se démode à la première ligne ajoutée, et c'est arrivé trois fois en
// deux jours — l'échéance de certificat, les arbres, la ligne vide sous chaque
// graphe.
func (m Model) gridHeight(t tier) int {
	columns := m.columnsFor(t)
	total := leadingBlank
	for _, height := range m.innerHeights(columns, t.columnWidth(m.width), t) {
		total += height + theme.BoxChrome
	}
	return total
}

// leadingBlank is the empty line between the title rule and the first row.
const leadingBlank = 1

// Box geometry. Les boîtes empilées ne sont pas séparées par une ligne vide :
// leurs bordures s'en chargent, et à 30 lignes le budget est exactement de
// deux boîtes (2 × (6 + 2) = 16).
//
// nominalInnerHeight ne sert qu'à exprimer les seuils de palier : la hauteur
// réelle d'une boîte est *dérivée des sections à l'écran* (voir innerHeight
// dans view.go), donc une section qui grandit ne peut pas être tronquée par une
// constante que personne n'a pensé à suivre.
const (
	nominalInnerHeight = 6
	columnGap          = 1
	sidePadding        = 1
)

// layoutTier is the only thing that decides a palier. Aucun renderer ne calcule
// le sien : deux règles de palier, et les boîtes d'une même grille cessent de
// s'accorder sur leur hauteur.
func layoutTier(width, height int) tier {
	switch {
	case width >= wideMinWidth && height >= wideMinHeight:
		return tierWide
	case width >= standardMinWidth:
		return tierStandard
	default:
		return tierCompact
	}
}

// columns returns how many columns of boxes the palier lays out.
func (t tier) columns() int {
	switch t {
	case tierWide:
		return 3
	case tierStandard:
		return 2
	default:
		return 1
	}
}

// tabCountFor returns how many tabs the palier offers. À `wide`, la troisième
// colonne porte déjà les boîtes de Resources : proposer l'onglet en plus
// afficherait deux fois les mêmes trois boîtes, ce qui est précisément la
// duplication qu'un onglet est censé éviter.
//
// Il n'y a donc pas de barre d'onglets à `wide` : un seul onglet n'est pas un
// choix, et la barre dirait « vous êtes ici », ce que l'écran dit déjà.
//
// Ça demande que `App.resize` itère : il interroge la vue sur la hauteur de son
// footer avant de lui communiquer sa nouvelle taille, donc une barre qui
// apparaît avec le palier répondrait d'après la taille précédente. Deux passes
// suffisent, et la seconde interroge une vue qui connaît sa taille.
func tabCountFor(t tier) int {
	if t == tierWide {
		return 1
	}
	return int(tabCount)
}

// columnWidth returns the width of one box column for a total view width.
func (t tier) columnWidth(width int) int {
	n := t.columns()
	available := width - 2*sidePadding - columnGap*(n-1)
	return max(available/n, minColumnWidth)
}

// minColumnWidth is the narrowest column that still holds a label and a value.
const minColumnWidth = 24

// BlurredTableStyles retourne les styles pour une table qui n'a pas le focus
func BlurredTableStyles() table.Styles {
	s := table.DefaultStyles()

	s.Header = s.Header.
		Background(ColorBackground).
		Foreground(ColorTableHeaderFg).
		Bold(true)

	s.Selected = s.Selected.
		Background(ColorBackground).
		Foreground(ColorText).
		Bold(false)

	return s
}

